import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
} from "../src/pricing.ts";
import { RegionalTaxCalculator, NoTaxCalculator } from "../src/tax.ts";
import {
  FlatShippingCalculator,
  FreeShippingCalculator,
} from "../src/shipping.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500 };

describe("Cart — line management", () => {
  it("starts with 0 items and zero totals", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("adds products and sums quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
    expect(cart.totals().subtotalCents).toBe(2000);
  });

  it("merges quantities when adding same product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.totals().subtotalCents).toBe(5000);
  });

  it("rejects non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updateQuantity changes the quantity", () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.updateQuantity("a", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("updateQuantity(0) removes the product", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 1)).toThrow();
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.totals().subtotalCents).toBe(0);
  });

  it("snapshot returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart — pricing pipeline", () => {
  it("applies discount then tax on discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ US: 0.1 }),
      region: "US",
    });
    cart.add(productA, 10); // subtotal 10000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(10000);
    expect(t.discountCents).toBe(1000); // 10%
    expect(t.taxCents).toBe(900); // 10% of 9000
    expect(t.shippingCents).toBe(0); // default free
    expect(t.totalCents).toBe(9900); // 9000 + 900
  });

  it("clamps discount to [0, subtotal]", () => {
    // A policy returning more than subtotal
    const bigDiscount: DiscountPolicy = {
      computeDiscountCents: () => 999999,
    };
    const cart = new Cart({ discountPolicy: bigDiscount });
    cart.add(productA, 1); // subtotal 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(1000);
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const negTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShipping: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("computes shipping on discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(5000),
      shippingCalculator: new FlatShippingCalculator(500, 6000),
    });
    cart.add(productA, 10); // subtotal 10000, discount 5000, discounted = 5000
    const t = cart.totals();
    // discounted subtotal 5000 < freeOver 6000 → shipping 500
    expect(t.shippingCents).toBe(500);
  });

  it("uses defaults when no config given", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });
});

describe("Cart — checkout()", () => {
  it("works with no collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher: fetcher });
    expect(result.totals.subtotalCents).toBe(3000); // 1500 × 2
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("throws InventoryError when item unavailable", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, availableQuantity: 0, reason: "sold out" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(5);
      expect(ie.message).toBe("sold out");
    }
  });

  it("throws InventoryError on partial stock denial", async () => {
    const cart = new Cart();
    cart.add(productA, 10);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("passes when inventory is available", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US-CA",
    });
    cart.add(productA, 10); // subtotal 10000
    const asyncTax: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider: asyncTax });
    // discount 1000, discounted 9000, tax = floor(9000 * 0.0875) = 787
    expect(result.totals.discountCents).toBe(1000);
    expect(result.totals.taxCents).toBe(787);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(9000 + 787 + 500);
    expect(asyncTax.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("propagates asyncTaxProvider error", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const asyncTax: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider: asyncTax })).rejects.toThrow(
      "tax service down",
    );
  });

  it("propagates priceFetcher error", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API error")),
    };
    await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
      "price API error",
    );
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({
      discountPolicy: new NoDiscountPolicy(),
      shippingCalculator: new FreeShippingCalculator(),
      region: "DE",
    });
    cart.add(productA, 1);
    cart.add(productB, 2);

    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(800)  // product a
        .mockResolvedValueOnce(2000), // product b
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTax: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.19),
    };

    const result = await cart.checkout({
      priceFetcher: fetcher,
      inventoryChecker: checker,
      asyncTaxProvider: asyncTax,
    });
    // subtotal: 800 + 2*2000 = 4800, no discount, tax = floor(4800*0.19) = 912
    expect(result.totals.subtotalCents).toBe(4800);
    expect(result.totals.taxCents).toBe(912);
    expect(result.totals.totalCents).toBe(4800 + 912);
    expect(checker.check).toHaveBeenCalledTimes(2);
  });

  it("checkout with empty cart", async () => {
    const cart = new Cart();
    const result = await cart.checkout();
    expect(result.totals.totalCents).toBe(0);
    expect(result.lines).toHaveLength(0);
  });
});

