import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any lines and subtotal", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 2)], 10000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(10.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(500);
    expect(calc.computeShippingCents([], 10000)).toBe(0);
  });

  it("returns flat fee for non-empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([makeLine("a", 200, 1)], 5000)).toBe(599);
  });

  it("returns 0 when subtotal meets free-over threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([makeLine("a", 200, 1)], 5000)).toBe(0);
  });

  it("returns 0 when subtotal exceeds free-over threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([makeLine("a", 200, 1)], 6000)).toBe(0);
  });

  it("charges when subtotal is below free-over threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([makeLine("a", 200, 1)], 4999)).toBe(599);
  });

  it("allows 0 flatCents", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([makeLine("a", 200, 1)], 1000)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 100, costCents: 500 }],
          10.5,
        ),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 100, costCents: 500 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 10000)).toBe(0);
  });

  it("returns 0 when total weight is 0 (no weightGrams)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(
      calc.computeShippingCents([makeLine("a", undefined, 2)], 5000),
    ).toBe(0);
  });

  it("selects the correct bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 2000, costCents: 1000 },
    ]);
    // 400g → first bracket
    expect(calc.computeShippingCents([makeLine("a", 400, 1)], 5000)).toBe(300);
    // 800g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 800, 1)], 5000)).toBe(600);
    // 1500g → third bracket
    expect(calc.computeShippingCents([makeLine("a", 1500, 1)], 5000)).toBe(1000);
  });

  it("selects bracket at exact boundary (weight == upToGrams)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // exactly 500g → first bracket
    expect(calc.computeShippingCents([makeLine("a", 500, 1)], 5000)).toBe(300);
    // exactly 1000g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 5000)).toBe(600);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      1500,
    );
    expect(calc.computeShippingCents([makeLine("a", 1500, 1)], 5000)).toBe(1500);
  });

  it("falls back to heaviest bracket cost when no overflow is set", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 5000)).toBe(600);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 2000, costCents: 1000 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 400, 1)], 5000)).toBe(300);
  });

  it("multiplies weight by quantity", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 200g × 3 = 600g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 200, 3)], 5000)).toBe(600);
  });
});

